import * as T from './vendor/three.module.js';
import {buildCar} from './scene.js';
import {ROAD,LANES,lanePose,centerGeometry,signalState,mod} from './road-core.js';
const material=(color,extra={})=>new T.MeshStandardMaterial({color,roughness:.8,...extra});
function meshBox(parent,size,position,mat){const m=new T.Mesh(new T.BoxGeometry(...size),mat);m.position.set(...position);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function roadRibbon(a,b,y,mat){const positions=[],ids=[];for(let i=0;i<ROAD.points.length;i++){const p=ROAD.points[i],g=centerGeometry(ROAD.distances[i]);for(const offset of [a,b])positions.push(p.x+Math.cos(g.heading)*offset,y,p.z-Math.sin(g.heading)*offset);if(i<ROAD.points.length-1){const k=i*2;ids.push(k,k+2,k+1,k+1,k+2,k+3);}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setIndex(ids);geo.computeVertexNormals();const m=new T.Mesh(geo,mat);m.receiveShadow=true;return m;}
function label(text,bg='#24383e',fg='#f1efdf'){const c=document.createElement('canvas');c.width=512;c.height=128;const ctx=c.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,512,128);ctx.fillStyle=fg;ctx.font='bold 48px sans-serif';ctx.textAlign='center';ctx.fillText(text,256,83);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;return new T.MeshBasicMaterial({map:tex,side:T.DoubleSide});}
function instance(parent,geometry,mat,transforms){const m=new T.InstancedMesh(geometry,mat,transforms.length),o=new T.Object3D();transforms.forEach((t,i)=>{o.position.set(...t.p);o.rotation.set(0,t.r||0,0);o.scale.set(...(t.s||[1,1,1]));o.updateMatrix();m.setMatrixAt(i,o.matrix);if(t.color)m.setColorAt(i,new T.Color(t.color));});m.receiveShadow=true;parent.add(m);return m;}
const COLORS=['#cbdc72','#db8262','#82b7c1','#dedbd0','#a79bc2','#b9b9b1','#e2bc68','#70a99c'];
class Fleet{
 constructor(scene,cars){this.group=new T.Group();scene.add(this.group);this.parts=[];const template=buildCar();template.updateMatrixWorld(true);template.traverse(o=>{if(!o.isMesh)return;const mat=o.material.clone();if(o.material.color?.getHexString()==='dce86c')mat.color.set('#ffffff');const m=new T.InstancedMesh(o.geometry,mat,cars.length);m.castShadow=o.castShadow;m.receiveShadow=true;m.userData.carPart=true;m.instanceMatrix.setUsage(T.DynamicDrawUsage);if(o.material.color?.getHexString()==='dce86c')cars.forEach((c,i)=>m.setColorAt(i,new T.Color(COLORS[c.id%COLORS.length])));this.group.add(m);this.parts.push({mesh:m,local:o.matrixWorld.clone(),front:template.userData.front.includes(o.parent)?o.parent.position.clone():null,child:o.matrix.clone()});});this.root=new T.Matrix4();this.rotation=new T.Quaternion();this.temp=new T.Matrix4();this.local=new T.Matrix4();this.axis=new T.Vector3(0,1,0);this.position=new T.Vector3();}
 update(cars,hidden=-1){for(let i=0;i<cars.length;i++){const c=cars[i],p=lanePose(c.s,c.lane,c.e,c.h);this.rotation.setFromAxisAngle(this.axis,p.yaw);this.position.set(p.x,.02,p.z);const scale=i===hidden ? .00001 : 1;this.root.compose(this.position,this.rotation,new T.Vector3(scale,scale,scale));for(const part of this.parts){if(part.front){this.local.makeTranslation(part.front.x,part.front.y,part.front.z);this.temp.makeRotationY(c.wheel);this.local.multiply(this.temp).multiply(part.child);}else this.local.copy(part.local);this.temp.multiplyMatrices(this.root,this.local);part.mesh.setMatrixAt(i,this.temp);}}this.parts.forEach(p=>p.mesh.instanceMatrix.needsUpdate=true);}
 dispose(){this.group.traverse(o=>{if(o.material){o.material.map?.dispose();o.material.dispose();}if(o.geometry)o.geometry.dispose();});this.group.removeFromParent();}
}
function human(color){const g=new T.Group(),cloth=material(color),skin=material('#c99877'),trousers=material('#35454c');meshBox(g,[.34,.55,.23],[0,1.04,0],cloth);const head=new T.Mesh(new T.SphereGeometry(.17,9,7),skin);head.position.y=1.5;g.add(head);g.userData.legs=[];for(const x of [-.105,.105]){const leg=meshBox(g,[.13,.66,.14],[x,.42,0],trousers);g.userData.legs.push(leg);meshBox(g,[.1,.52,.11],[x*2.25,1.02,0],cloth);}return g;}
function dog(){const g=new T.Group(),fur=material('#aa784c'),dark=material('#4d392b');meshBox(g,[.32,.3,.67],[0,.45,0],fur);meshBox(g,[.28,.27,.27],[0,.63,.36],fur);meshBox(g,[.17,.12,.18],[0,.58,.54],dark);for(const x of [-.12,.12]){meshBox(g,[.08,.2,.13],[x,.81,.35],dark);for(const z of [-.22,.22])meshBox(g,[.07,.32,.09],[x,.21,z],fur);}const tail=meshBox(g,[.07,.08,.36],[0,.59,-.46],dark);tail.rotation.x=-.5;g.userData.tail=tail;return g;}
export class RoadScene{
 constructor(container,world,onSelect){this.container=container;this.scene=new T.Scene();this.scene.background=new T.Color('#bed3d7');this.scene.fog=new T.Fog('#bed3d7',330,850);this.renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.15;this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=T.PCFSoftShadowMap;container.prepend(this.renderer.domElement);this.camera=new T.PerspectiveCamera(48,1,.1,1200);this.scene.add(new T.HemisphereLight('#dfeef4','#626a55',2.3));const sun=new T.DirectionalLight('#ffedcd',2.7);sun.position.set(-130,240,100);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-220;sun.shadow.camera.right=220;sun.shadow.camera.top=230;sun.shadow.camera.bottom=-230;sun.shadow.camera.far=700;sun.shadow.bias=-.0008;this.scene.add(sun);this.staticWorld=new T.Group();this.scene.add(this.staticWorld);this.actorModels=new Map();const leashGeometry=new T.BufferGeometry();leashGeometry.setAttribute('position',new T.Float32BufferAttribute([0,0,0,0,0,0],3));this.leash=new T.Line(leashGeometry,new T.LineBasicMaterial({color:'#514d3e'}));this.scene.add(this.leash);this.lights=[];this.view='overview';this.selected=0;this.snap=true;this.build(world);this.fleet=new Fleet(this.scene,world.cars);this.selectedRing=new T.Mesh(new T.TorusGeometry(1.7,.07,6,36),new T.MeshBasicMaterial({color:'#d7f878'}));this.selectedRing.rotation.x=Math.PI/2;this.scene.add(this.selectedRing);this.raycaster=new T.Raycaster();this.renderer.domElement.addEventListener('click',e=>{const r=this.renderer.domElement.getBoundingClientRect();this.raycaster.setFromCamera(new T.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),this.camera);const hit=this.raycaster.intersectObjects(this.fleet.group.children,false)[0];if(hit?.instanceId!==undefined)onSelect(hit.instanceId);});new ResizeObserver(()=>this.resize()).observe(container);this.resize();}
 resize(){const w=this.container.clientWidth,h=this.container.clientHeight;this.renderer.setSize(w,h);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();this.snap=true;}
 build(world){const group=this.staticWorld,asphalt=material('#555e60'),walk=material('#c1beb1'),curb=material('#d9d5c4'),white=new T.MeshBasicMaterial({color:'#f0eee0'}),yellow=new T.MeshBasicMaterial({color:'#dfc77b'});const ground=new T.Mesh(new T.PlaneGeometry(1700,1700),material('#8b9e7a'));ground.rotation.x=-Math.PI/2;ground.position.y=-.05;ground.receiveShadow=true;group.add(ground);group.add(roadRibbon(-7.2,7.2,.015,asphalt));for(const side of [-1,1]){group.add(roadRibbon(side===1?7.2:-11,side===1?11:-7.2,.17,walk));group.add(roadRibbon(side*7.2-.12,side*7.2+.12,.2,curb));group.add(roadRibbon(side*7.02-.04,side*7.02+.04,.028,white));group.add(roadRibbon(side*.13-.035,side*.13+.035,.03,yellow));}
 const dashes=[],trees=[],trunks=[],lamps=[];for(let s=0;s<ROAD.length;s+=6){const g=centerGeometry(s);for(const off of [-3.6,3.6])dashes.push({p:[g.x+Math.cos(g.heading)*off,.028,g.z-Math.sin(g.heading)*off],r:g.heading,s:[.1,.01,2.6]});if(s%24===0){for(const off of [-12.5,12.5]){if(world.crossings.some(c=>Math.min(mod(c.s-s),mod(s-c.s))<12))continue;const x=g.x+Math.cos(g.heading)*off,z=g.z-Math.sin(g.heading)*off;trunks.push({p:[x,1.5,z],s:[.25,3,.25]});trees.push({p:[x,4.2,z],s:[2.3,3.4,2.3],color:s%48?'#5b795b':'#77905e'});}}}
 const arrows=[];for(let s=15;s<ROAD.length;s+=48){if(world.crossings.some(c=>Math.min(mod(c.s-s),mod(s-c.s))<15))continue;for(let lane=0;lane<4;lane++){const p=lanePose(s,lane);arrows.push({p:[p.x,.035,p.z],r:p.yaw});}}const arrowGeometry=new T.BufferGeometry();arrowGeometry.setAttribute('position',new T.Float32BufferAttribute([-.09,0,-1,.09,0,-1,-.09,0,.3,.09,0,.3,-.42,0,.25,.42,0,.25,0,0,1],3));arrowGeometry.setIndex([0,2,1,1,2,3,4,6,5]);instance(group,arrowGeometry,white,arrows);instance(group,new T.BoxGeometry(1,1,1),white,dashes);instance(group,new T.CylinderGeometry(1,1,1,6),material('#796751'),trunks);instance(group,new T.IcosahedronGeometry(1,1),material('#ffffff',{flatShading:true}),trees);
 const windows=[];for(const side of [-1,1])for(let z=-150;z<=150;z+=32){const idx=Math.round((z+150)/32),height=8+(idx%4)*4,x=side*(102+(idx%2)*9),length=20;meshBox(group,[17,height,length],[x,height/2,z],material(['#bac4bd','#d6c6ac','#98aeb0','#b0aaa0'][idx%4]));meshBox(group,[18,.45,21],[x,height+.2,z],material('#7a8c88'));for(let floor=2;floor<height-1;floor+=3)for(let zz=-7;zz<=7;zz+=3.5)windows.push({p:[x-side*8.55,floor,z+zz],r:0,s:[.1,1.45,2],color:idx%3?'#54737b':'#89a1a2'});const sign=new T.Mesh(new T.PlaneGeometry(13,1.4),label(['MARKET','BAKERY','LIBRARY','STUDIO'][idx%4]));sign.position.set(x-side*8.6,2,z);sign.rotation.y=-side*Math.PI/2;group.add(sign);}
 instance(group,new T.BoxGeometry(1,1,1),material('#ffffff',{metalness:.2}),windows);
 const paths=material('#b9b89c');meshBox(group,[65,.04,3],[0,.01,0],paths);meshBox(group,[3,.04,270],[0,.01,0],paths);for(let z=-130;z<=130;z+=40){meshBox(group,[3,.1,1],[-22,.35,z],material('#a4845e'));meshBox(group,[.2,.5,.8],[-23,.1,z],material('#455c55'));meshBox(group,[.2,.5,.8],[-21,.1,z],material('#455c55'));}
 for(const cross of world.crossings){const g=centerGeometry(cross.s),zebra=new T.Group();zebra.position.set(g.x,.03,g.z);zebra.rotation.y=g.heading;group.add(zebra);for(let x=-7;x<7;x+=1.1)meshBox(zebra,[.6,.01,4.4],[x,.01,0],white);for(const dir of [-1,1]){const stop=centerGeometry(cross.s-dir*5.6),line=new T.Mesh(new T.BoxGeometry(6.8,.012,.22),white);line.position.set(stop.x+Math.cos(stop.heading)*(dir*3.6),.031,stop.z-Math.sin(stop.heading)*(dir*3.6));line.rotation.y=stop.heading;group.add(line);const off=dir*8.5,pole=new T.Group();pole.position.set(stop.x+Math.cos(stop.heading)*off,.18,stop.z-Math.sin(stop.heading)*off);pole.rotation.y=stop.heading+(dir===-1?Math.PI:0);group.add(pole);meshBox(pole,[.13,4.8,.13],[0,2.4,0],material('#536968'));meshBox(pole,[.58,1.45,.42],[0,4.5,0],material('#263b3d'));const balls=[];for(let i=0;i<3;i++){const light=new T.Mesh(new T.SphereGeometry(.16,10,8),new T.MeshStandardMaterial({color:['#e55c4c','#e6ba5e','#a6d67a'][i],emissive:['#e55c4c','#e6ba5e','#a6d67a'][i],emissiveIntensity:.1}));light.position.set(0,4.95-i*.45,-.24);pole.add(light);balls.push(light);}this.lights.push({crossing:cross.id,balls});const speed=new T.Mesh(new T.PlaneGeometry(1.2,1.2),label('50','#eee9d8','#344548'));speed.position.set(0,2.1,-.1);pole.add(speed);}}
 for(const side of [-1,1])for(let z=-125;z<150;z+=50){const x=side*76;meshBox(group,[.11,7,.11],[x,3.5,z],material('#687d79'));meshBox(group,[2.8,.12,.3],[x-side*1.2,7,z],material('#687d79'));meshBox(group,[1.4,.07,.4],[x-side*2,6.9,z],material('#e5ddbe'));}
 const title=new T.Mesh(new T.PlaneGeometry(24,4),label('OPENNEURAL SQUARE'));title.position.set(0,3,-80);group.add(title);}
 resetFleet(world){this.fleet.dispose();this.fleet=new Fleet(this.scene,world.cars);this.selected=Math.min(this.selected,world.cars.length-1);this.snap=true;}
 select(id,view='chase'){this.selected=id;this.view=view;this.snap=true;}
 update(world,dt){const car=world.cars[this.selected]||world.cars[0],p=lanePose(car.s,car.lane,car.e,car.h);this.fleet.update(world.cars,this.view==='pov'?this.selected:-1);this.selectedRing.position.set(p.x,.055,p.z);this.selectedRing.visible=this.view!=='pov';
  const active=new Set();for(const actor of world.actors){active.add(actor.id);let g=this.actorModels.get(actor.id);if(!g){g=actor.kind==='dog'?dog():human(['#de9b78','#9eafa2','#7da0b7','#c7b86f'][this.actorModels.size%4]);this.actorModels.set(actor.id,g);this.scene.add(g);}g.visible=true;g.position.set(actor.x,actor.inRoad?0:.18,actor.z);g.rotation.y=actor.yaw;if(g.userData.legs)g.userData.legs.forEach((leg,i)=>leg.rotation.x=actor.walking?Math.sin(world.time*7+i*Math.PI)*.35:0);if(g.userData.tail)g.userData.tail.rotation.y=Math.sin(world.time*8)*.45;}
  for(const [id,g] of this.actorModels)if(!active.has(id))g.visible=false;const leashed=world.actors.find(a=>a.leashedTo),owner=leashed&&world.actors.find(a=>a.id===leashed.leashedTo);this.leash.visible=!!owner;if(owner){const positions=this.leash.geometry.attributes.position;positions.setXYZ(0,leashed.x,.75,leashed.z);positions.setXYZ(1,owner.x,1.2,owner.z);positions.needsUpdate=true;this.leash.geometry.computeBoundingSphere();}
  for(const l of this.lights){const phase=signalState(world.time,world.crossings[l.crossing].offset).phase,index=phase==='red'?0:phase==='amber'?1:2;l.balls.forEach((m,i)=>{m.material.emissiveIntensity=i===index?1.8:0;m.material.color.set(i===index?['#ed6353','#e4bd66','#b7e28c'][i]:'#344843');});}
  let desired,look;if(this.view==='overview'){const ratio=Math.max(1,1.5/this.camera.aspect);desired=new T.Vector3(235*ratio,280*ratio,285*ratio);look=new T.Vector3(0,0,0);}else{const f=new T.Vector3(Math.sin(p.yaw),0,Math.cos(p.yaw)),r=new T.Vector3(Math.cos(p.yaw),0,-Math.sin(p.yaw)),center=new T.Vector3(p.x,0,p.z);if(this.view==='pov'){desired=center.clone().addScaledVector(f,.6);desired.y=1.4;look=center.clone().addScaledVector(f,25);look.y=1.25;}else{desired=center.clone().addScaledVector(f,-9).addScaledVector(r,1.6);desired.y=5;look=center.clone().addScaledVector(f,14);look.y=.8;}}this.camera.position.lerp(desired,this.snap?1:1-Math.exp(-dt*7));this.camera.lookAt(look);this.snap=false;this.renderer.render(this.scene,this.camera);}
}
